package com.projectsale.api.catalog.entity;
import com.projectsale.api.user.entity.EntityStatus; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="brands") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class Brand { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="public_id",nullable=false,unique=true,insertable=false,updatable=false) private UUID publicId; @Column(nullable=false,length=120) private String name; @Column(nullable=false,unique=true,length=150) private String slug; @Column(name="logo_url") private String logoUrl; private String info; @Column(name="meta_title") private String metaTitle; @Column(name="meta_description") private String metaDescription; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="entity_status") private EntityStatus status; @Column(name="deleted_at") private Instant deletedAt; public boolean visible(){return status==EntityStatus.ACTIVE&&deletedAt==null;} }
